function ed.initCurChooseLan()
  EDCurLanguage = CCUserDefault:sharedUserDefault():getStringForKey("_default_language_")
  if EDCurLanguage == "" then
    EDCurLanguage = "cn"
  end
  EDCurLilithLanguage = lilith_language_code[EDCurLanguage]
  return EDCurLanguage
end

local function refreshSoundSearchPaths(soundLan)
  EDLog("EDCurSoundLan refreshSoundSearchPaths:" .. soundLan)
  CCUserDefault:sharedUserDefault():setStringForKey("_default_sound_", soundLan)
  EDCurSoundLan = soundLan
  EDFilePath:getInstance():setCurSound(soundLan)
  EDFilePath:getInstance():refreshSearchPaths()
  EDLog("EDCurSoundLan:" .. EDCurSoundLan)
end

function ed.initCurChooseSoundLan()
  EDCurSoundLan = CCUserDefault:sharedUserDefault():getStringForKey("_default_sound_")
  EDLog("EDCurSoundLan initCurChooseSoundLan:" .. EDCurSoundLan)
  if EDCurSoundLan == "" then
    refreshSoundSearchPaths(default_sound or "cn")
  end
  if EDCurSoundLan == "ko" or EDCurSoundLan == "ja" then
    refreshSoundSearchPaths("en")
  end
  return EDCurSoundLan
end

function ed.setCurLan(lan)
  CCUserDefault:sharedUserDefault():setStringForKey("_default_language_", lan)
  ed.initCurChooseLan()
end

function ed.setCurSoundLan(lan)
  CCUserDefault:sharedUserDefault():setStringForKey("_default_sound_", lan)
  ed.initCurChooseSoundLan()
end

local mult_iaps = {
  [302] = {
    android = "Google iap",
    default = "Appstore iap"
  },
  [501] = {
    android = "Global Google iap",
    default = "Global Appstore iap"
  }
}
ed.mult_iaps = mult_iaps

function ed.getIAPTitle()
  local iap = ed.mult_iaps[EDSDKType]
  if iap == nil then
    iap = ed.mult_iaps[302]
  end
  if EDFLAGANDROID then
    return iap.android
  end
  return iap.default
end

function ed.getCurArea()
  return EDCurLanguage
end

ed.areaByLan = not not EDFLAGWIN32

function ed.isAreaOverSea()
  if ed.areaByLan then
    return EDCurLanguage ~= "cn"
  else
    return EDSDKType > 500
  end
end

function ed.isAreaZh()
  return EDCurLanguage == "tw" or EDCurLanguage == "cn"
end

function ed.isAreaZhCn()
  return EDCurLanguage == "cn"
end

function ed.isAreaZhTW()
  return EDCurLanguage == "tw"
end

function ed.isAreaJapan()
  return EDCurLanguage == "ja"
end

function ed.isAreaKorea()
  return EDCurLanguage == "ko"
end

function ed.isAreaSEA()
  return EDCurLanguage == "en"
end

function ed.isAreaUS()
  return EDCurLanguage == "en"
end

function ed.isMultiLanguage()
  return EDSDKType > 500
end

ed.initCurChooseLan()
ed.initCurChooseSoundLan()
