local function Trans2LilithCode(language)
  if language == "" then
    return language
  end
  local lower_language = language:lower()
  for key, value in pairs(tmp_trans_lang) do
    if lower_language:sub(1, #key) == key then
      return value
    end
  end
  return language
end

function ed.deviceLanguage()
  local lang = EDGetParam("lilithLanguage") or ""
  if lang == "" then
    lang = EDGetParam("deviceLanguage") or ""
    lang = Trans2LilithCode(lang)
  end
  return lang
end
